// Indirect-params (exercises Lift indirect-params path C):
//   17 u32 params + u32 result.
//   Core function takes single ptr, loads u32 at offset 64 (param 16), returns.
TEST(ComponentCanonInvoke, IndirectParams17U32) {
  Configure Conf;
  Conf.addProposal(Proposal::Component);
  VM::ComponentVM VM(Conf);

  std::vector<uint8_t> Vec = {
      0x00, 0x61, 0x73, 0x6d, 0x0d, 0x00, 0x01, 0x00, 0x01, 0x58, 0x00, 0x61,
      0x73, 0x6d, 0x01, 0x00, 0x00, 0x00, 0x01, 0x0e, 0x02, 0x60, 0x01, 0x7f,
      0x01, 0x7f, 0x60, 0x04, 0x7f, 0x7f, 0x7f, 0x7f, 0x01, 0x7f, 0x03, 0x03,
      0x02, 0x00, 0x01, 0x05, 0x03, 0x01, 0x00, 0x01, 0x07, 0x18, 0x03, 0x03,
      0x6d, 0x65, 0x6d, 0x02, 0x00, 0x04, 0x73, 0x69, 0x6e, 0x6b, 0x00, 0x00,
      0x07, 0x72, 0x65, 0x61, 0x6c, 0x6c, 0x6f, 0x63, 0x00, 0x01, 0x0a, 0x0f,
      0x02, 0x07, 0x00, 0x20, 0x00, 0x28, 0x02, 0x40, 0x0b, 0x05, 0x00, 0x41,
      0x80, 0x02, 0x0b, 0x00, 0x09, 0x04, 0x6e, 0x61, 0x6d, 0x65, 0x00, 0x02,
      0x01, 0x6d, 0x02, 0x04, 0x01, 0x00, 0x00, 0x00, 0x06, 0x1e, 0x03, 0x00,
      0x02, 0x01, 0x00, 0x03, 0x6d, 0x65, 0x6d, 0x00, 0x00, 0x01, 0x00, 0x07,
      0x72, 0x65, 0x61, 0x6c, 0x6c, 0x6f, 0x63, 0x00, 0x00, 0x01, 0x00, 0x04,
      0x73, 0x69, 0x6e, 0x6b, 0x07, 0x50, 0x01, 0x40, 0x11, 0x02, 0x70, 0x30,
      0x79, 0x02, 0x70, 0x31, 0x79, 0x02, 0x70, 0x32, 0x79, 0x02, 0x70, 0x33,
      0x79, 0x02, 0x70, 0x34, 0x79, 0x02, 0x70, 0x35, 0x79, 0x02, 0x70, 0x36,
      0x79, 0x02, 0x70, 0x37, 0x79, 0x02, 0x70, 0x38, 0x79, 0x02, 0x70, 0x39,
      0x79, 0x03, 0x70, 0x31, 0x30, 0x79, 0x03, 0x70, 0x31, 0x31, 0x79, 0x03,
      0x70, 0x31, 0x32, 0x79, 0x03, 0x70, 0x31, 0x33, 0x79, 0x03, 0x70, 0x31,
      0x34, 0x79, 0x03, 0x70, 0x31, 0x35, 0x79, 0x03, 0x70, 0x31, 0x36, 0x79,
      0x00, 0x79, 0x08, 0x0a, 0x01, 0x00, 0x00, 0x01, 0x02, 0x03, 0x00, 0x04,
      0x00, 0x00, 0x0b, 0x0a, 0x01, 0x00, 0x04, 0x73, 0x69, 0x6e, 0x6b, 0x01,
      0x00, 0x00, 0x00, 0x3c, 0x0e, 0x63, 0x6f, 0x6d, 0x70, 0x6f, 0x6e, 0x65,
      0x6e, 0x74, 0x2d, 0x6e, 0x61, 0x6d, 0x65, 0x01, 0x09, 0x00, 0x00, 0x02,
      0x00, 0x01, 0x72, 0x01, 0x01, 0x66, 0x01, 0x08, 0x00, 0x02, 0x01, 0x00,
      0x03, 0x6d, 0x65, 0x6d, 0x01, 0x06, 0x00, 0x11, 0x01, 0x00, 0x01, 0x6d,
      0x01, 0x06, 0x00, 0x12, 0x01, 0x00, 0x01, 0x69, 0x01, 0x06, 0x03, 0x01,
      0x00, 0x02, 0x66, 0x74};

  ASSERT_TRUE(VM.loadWasm(Vec));
  ASSERT_TRUE(VM.validate());
  ASSERT_TRUE(VM.instantiate());

  std::vector<ComponentValVariant> Params;
  std::vector<ComponentValType> PTypes;
  Params.reserve(17);
  PTypes.reserve(17);
  for (uint32_t I = 0; I < 17; ++I) {
    // Distinct sentinel values; index 16 (last) is 0xDEADBEEF so we can
    // assert the core function picked the right offset.
    Params.emplace_back(I == 16u ? 0xDEADBEEFu : (0x1000u + I));
    PTypes.emplace_back(ComponentTypeCode::U32);
  }
  auto Res = VM.execute("sink", Params, PTypes);
  ASSERT_TRUE(Res);
  ASSERT_EQ(Res->size(), 1u);
  // Single direct-return u32, typed-arm convention end-to-end.
  auto Ret = std::get<uint32_t>((*Res)[0].first);
  EXPECT_EQ(Ret, 0xDEADBEEFu);
}

