// TypeIndex tuple param (exercises the lower path for a nested aggregate):
//   (param (tuple u32 u32)) -> u32 ; core function sums and returns.
TEST(ComponentCanonInvoke, TypeIndexTupleParamDirect) {
  Configure Conf;
  Conf.addProposal(Proposal::Component);
  VM::ComponentVM VM(Conf);

  std::vector<uint8_t> Vec = {
      0x00, 0x61, 0x73, 0x6d, 0x0d, 0x00, 0x01, 0x00, 0x01, 0x5c, 0x00, 0x61,
      0x73, 0x6d, 0x01, 0x00, 0x00, 0x00, 0x01, 0x0f, 0x02, 0x60, 0x02, 0x7f,
      0x7f, 0x01, 0x7f, 0x60, 0x04, 0x7f, 0x7f, 0x7f, 0x7f, 0x01, 0x7f, 0x03,
      0x03, 0x02, 0x00, 0x01, 0x05, 0x03, 0x01, 0x00, 0x01, 0x07, 0x1b, 0x03,
      0x03, 0x6d, 0x65, 0x6d, 0x02, 0x00, 0x07, 0x63, 0x6f, 0x6e, 0x73, 0x75,
      0x6d, 0x65, 0x00, 0x00, 0x07, 0x72, 0x65, 0x61, 0x6c, 0x6c, 0x6f, 0x63,
      0x00, 0x01, 0x0a, 0x0f, 0x02, 0x07, 0x00, 0x20, 0x00, 0x20, 0x01, 0x6a,
      0x0b, 0x05, 0x00, 0x41, 0x80, 0x02, 0x0b, 0x00, 0x09, 0x04, 0x6e, 0x61,
      0x6d, 0x65, 0x00, 0x02, 0x01, 0x6d, 0x02, 0x04, 0x01, 0x00, 0x00, 0x00,
      0x06, 0x21, 0x03, 0x00, 0x02, 0x01, 0x00, 0x03, 0x6d, 0x65, 0x6d, 0x00,
      0x00, 0x01, 0x00, 0x07, 0x72, 0x65, 0x61, 0x6c, 0x6c, 0x6f, 0x63, 0x00,
      0x00, 0x01, 0x00, 0x07, 0x63, 0x6f, 0x6e, 0x73, 0x75, 0x6d, 0x65, 0x07,
      0x0c, 0x02, 0x6f, 0x02, 0x79, 0x79, 0x40, 0x01, 0x01, 0x76, 0x00, 0x00,
      0x79, 0x08, 0x0a, 0x01, 0x00, 0x00, 0x01, 0x02, 0x03, 0x00, 0x04, 0x00,
      0x01, 0x0b, 0x0d, 0x01, 0x00, 0x07, 0x63, 0x6f, 0x6e, 0x73, 0x75, 0x6d,
      0x65, 0x01, 0x00, 0x00, 0x00, 0x3c, 0x0e, 0x63, 0x6f, 0x6d, 0x70, 0x6f,
      0x6e, 0x65, 0x6e, 0x74, 0x2d, 0x6e, 0x61, 0x6d, 0x65, 0x01, 0x09, 0x00,
      0x00, 0x02, 0x00, 0x01, 0x72, 0x01, 0x01, 0x66, 0x01, 0x08, 0x00, 0x02,
      0x01, 0x00, 0x03, 0x6d, 0x65, 0x6d, 0x01, 0x06, 0x00, 0x11, 0x01, 0x00,
      0x01, 0x6d, 0x01, 0x06, 0x00, 0x12, 0x01, 0x00, 0x01, 0x69, 0x01, 0x06,
      0x03, 0x01, 0x01, 0x02, 0x66, 0x74};

  ASSERT_TRUE(VM.loadWasm(Vec));
  ASSERT_TRUE(VM.validate());
  ASSERT_TRUE(VM.instantiate());

  // Build the tuple value: { 10, 20 } → expect sum 30.
  TupleVal Tv;
  Tv.Values.emplace_back(uint32_t{10u});
  Tv.Values.emplace_back(uint32_t{20u});
  auto Aggregate = std::make_shared<ValComp>();
  Aggregate->V = std::move(Tv);

  // The component-level param type is the TypeIndex for the (tuple u32 u32),
  // which is type 0 in this module's component type space (the only defined
  // value type is the tuple). The function type itself is type 1, but we
  // index ValTypes by the value-type index.
  std::vector<ComponentValVariant> Params{ComponentValVariant{Aggregate}};
  std::vector<ComponentValType> PTypes{ComponentValType(/*TypeIndex=*/0u)};
  auto Res = VM.execute("consume", Params, PTypes);
  ASSERT_TRUE(Res);
  ASSERT_EQ(Res->size(), 1u);
  auto Ret = std::get<uint32_t>((*Res)[0].first);
  EXPECT_EQ(Ret, 30u);
}

