// =============================================================================
// Phase 3 / E — canon lift post-return:
//   Lift function returns (tuple u32 u32); indirect-result → flat returns the
//   single i32 ptr (=16). The post-return option points at drop-pair, which
//   stores its arg into mem[0..4]. A second exported lift reads mem[0..4] back
//   so the test can verify post-return ran with the original flat_result.
