VM::ComponentVM newProbeVM() {
  Configure Conf;
  Conf.addProposal(Proposal::Component);
  return VM::ComponentVM(Conf);
}

// 1) Indirect-return ptr is misaligned (= 1, tuple<u32,u32> needs 4-byte
//    alignment). spec: trap_if(ptr != align_to(ptr, alignment(tuple)).
TEST(ComponentCanonProbe, IndirectReturnMisalignedPtrTraps) {
  auto VM = newProbeVM();
  ASSERT_TRUE(VM.loadWasm(Wat_Misaligned));
  ASSERT_TRUE(VM.validate());
  ASSERT_TRUE(VM.instantiate());
  std::vector<ComponentValVariant> P;
  std::vector<ComponentValType> PT;
  auto Res = VM.execute("get", P, PT);
  EXPECT_FALSE(Res);
}

// 2) Indirect-return ptr is bounds-valid for first 4 bytes but the tuple
//    requires 8 bytes — load_tuple must detect the OOB and trap.
//    spec: trap_if(ptr + elem_size(tuple) > len(memory)).
TEST(ComponentCanonProbe, IndirectReturnOOBPtrTraps) {
  auto VM = newProbeVM();
  ASSERT_TRUE(VM.loadWasm(Wat_OOB));
  ASSERT_TRUE(VM.validate());
  ASSERT_TRUE(VM.instantiate());
  std::vector<ComponentValVariant> P;
  std::vector<ComponentValType> PT;
  auto Res = VM.execute("get", P, PT);
  EXPECT_FALSE(Res);
}

// 3) Mixed-alignment tuple<u8, u64, u8, u32>. Validates that the load_tuple
//    layout honoured per-field alignment when reading the indirect-return
//    area: u8@0, u64@8, u8@16, u32@20.
TEST(ComponentCanonProbe, IndirectReturnMixedAlignTuple) {
  auto VM = newProbeVM();
  ASSERT_TRUE(VM.loadWasm(Wat_MixedAlign));
  ASSERT_TRUE(VM.validate());
  ASSERT_TRUE(VM.instantiate());
  std::vector<ComponentValVariant> P;
  std::vector<ComponentValType> PT;
  auto Res = VM.execute("get", P, PT);
  ASSERT_TRUE(Res);
  ASSERT_EQ(Res->size(), 1u);
  auto &Vc = std::get<std::shared_ptr<ValComp>>((*Res)[0].first);
  ASSERT_TRUE(Vc);
  auto &Tup = std::get<TupleVal>(Vc->V);
  ASSERT_EQ(Tup.Values.size(), 4u);
  EXPECT_EQ(std::get<uint8_t>(Tup.Values[0]), 0xAAu);
  EXPECT_EQ(std::get<uint64_t>(Tup.Values[1]), 0x1122334455667788ull);
  EXPECT_EQ(std::get<uint8_t>(Tup.Values[2]), 0xBBu);
  EXPECT_EQ(std::get<uint32_t>(Tup.Values[3]), 0x12345678u);
}

// 4) Indirect-param path: 17 u32 args forces the host->core path to call
//    realloc to lay out the parameter tuple. Here realloc returns 0; the
//    callee receives the ptr in i32 and reports it back. The spec doesn't
//    require a trap, but the implementation must not crash trying to write
//    at ptr=0.
TEST(ComponentCanonProbe, IndirectParamReallocReturnsZero) {
  auto VM = newProbeVM();
  ASSERT_TRUE(VM.loadWasm(Wat_ReallocZero));
  ASSERT_TRUE(VM.validate());
  ASSERT_TRUE(VM.instantiate());
  std::vector<ComponentValVariant> Args;
  std::vector<ComponentValType> PT;
  for (uint32_t I = 0; I < 17; ++I) {
    Args.emplace_back(I);
    PT.emplace_back(ComponentTypeCode::U32);
  }
  auto Res = VM.execute("f", Args, PT);
  // Either traps or succeeds; the goal is *no crash*. Whichever the
  // implementation does, GTEST notices.
  (void)Res;
  SUCCEED();
}

// 5) Indirect-return tuple<string, u32>. Exercises load of a string field
//    inside the indirect-return area + a primitive after it.
TEST(ComponentCanonProbe, IndirectReturnStringInTuple) {
  auto VM = newProbeVM();
  ASSERT_TRUE(VM.loadWasm(Wat_StringInTuple));
  ASSERT_TRUE(VM.validate());
  ASSERT_TRUE(VM.instantiate());
  std::vector<ComponentValVariant> P;
  std::vector<ComponentValType> PT;
  auto Res = VM.execute("get", P, PT);
  ASSERT_TRUE(Res);
  ASSERT_EQ(Res->size(), 1u);
  auto &Vc = std::get<std::shared_ptr<ValComp>>((*Res)[0].first);
  ASSERT_TRUE(Vc);
  auto &Tup = std::get<TupleVal>(Vc->V);
  ASSERT_EQ(Tup.Values.size(), 2u);
  EXPECT_EQ(std::get<std::string>(Tup.Values[0]), "hello");
  EXPECT_EQ(std::get<uint32_t>(Tup.Values[1]), 0x12345678u);
}

// 6) String length field > MAX_STRING_BYTE_LENGTH (2^28-1). Spec
//    load_string traps in this case (CanonicalABI.md region).
TEST(ComponentCanonProbe, IndirectReturnStringLenTooLargeTraps) {
  auto VM = newProbeVM();
  ASSERT_TRUE(VM.loadWasm(Wat_StringTooLong));
  ASSERT_TRUE(VM.validate());
  ASSERT_TRUE(VM.instantiate());
  std::vector<ComponentValVariant> P;
  std::vector<ComponentValType> PT;
  auto Res = VM.execute("get", P, PT);
  EXPECT_FALSE(Res);
}

// 7) Variant <a(s64) | b(f32)> wrapped in 1-tuple. Joined flat = [i32, i64].
//    Data: disc=1, payload's low i32 = bits-of(12.5f) = 0x41480000. The
//    indirect-load path goes through load_variant → load f32 at payload+0.
TEST(ComponentCanonProbe, IndirectReturnVariantJoinCoerce) {
  auto VM = newProbeVM();
  ASSERT_TRUE(VM.loadWasm(Wat_VariantJoin));
  ASSERT_TRUE(VM.validate());
  ASSERT_TRUE(VM.instantiate());
  std::vector<ComponentValVariant> P;
  std::vector<ComponentValType> PT;
  auto Res = VM.execute("get", P, PT);
  ASSERT_TRUE(Res);
  ASSERT_EQ(Res->size(), 1u);
  auto &Vc = std::get<std::shared_ptr<ValComp>>((*Res)[0].first);
  ASSERT_TRUE(Vc);
  auto &Tup = std::get<TupleVal>(Vc->V);
  ASSERT_EQ(Tup.Values.size(), 1u);
  auto &Vv = std::get<std::shared_ptr<ValComp>>(Tup.Values[0]);
  ASSERT_TRUE(Vv);
  auto &Variant = std::get<VariantVal>(Vv->V);
  EXPECT_EQ(Variant.Case, 1u);
  ASSERT_TRUE(Variant.Payload.has_value());
  EXPECT_FLOAT_EQ(std::get<float>(*Variant.Payload), 12.5f);
}

