// === option<u32> + result<u32,string> ===
// (component
//   (core module $m
//     (memory (export "mem") 1)
//     ;; Indirect-return area @16: tuple<option<u32>, result<u32, string>>.
//     ;; Layout (despecialized):
//     ;;   option<u32> → variant<none | some(u32)>:
//     ;;     +0  i8  disc = 1 (Some)
