// === s8/u8/s16/u16/f32/f64/char/bool ===
// (component
//   ;; Result tuple <s8 u8 s16 u16 f32 f64 char bool> covers all the lift_flat
//   ;; / lift_primitive arms that the existing tuple<u32,u32> test misses.
//   ;; Indirect-return area @16:
//   ;;   +0  s8  = -1                    (0xFF)
