// === canon-lower string round-trip ===
// (component
//   ;; Module M1 exports a core function "echo-len" that takes (ptr, len) and
//   ;; returns len. Lifted as comp-strlen with signature (string)->u32. Then
//   ;; lowered back to a core function and re-imported by M2; M2 exports
//   ;; "use-strlen" which calls it. We re-lift use-strlen so the host can
//   ;; invoke "strlen-via-roundtrip" with a string and read back its length —
