// === canon-lower tuple<u32,u32> round-trip ===
// (component
//   ;; M1 exports core "get-pair" that returns ptr-to-laid-out tuple<u32,u32>.
//   ;; Lifted as comp-get-pair: () -> tuple<u32,u32>. Result is too wide for
//   ;; flat (2 i32 > MAX_FLAT_RESULTS=1), so the canon lower must allocate a
//   ;; return area via realloc on M2's memory and copy the lowered tuple
//   ;; there. M2 imports the lowered core form, calls it with an out-pointer
//   ;; into its own memory, then reads back the first u32.
//   (core module $m1
//     (memory (export "mem") 1)
//     (data (i32.const 16) "\07\00\00\00\05\00\00\00")
//     (func (export "get-pair") (result i32) i32.const 16)
//     (func (export "realloc") (param i32 i32 i32 i32) (result i32) i32.const
//     256))
//   (core instance $i1 (instantiate $m1))
//   (alias core export $i1 "mem" (core memory $mem1))
//   (alias core export $i1 "realloc" (core func $r1))
//   (alias core export $i1 "get-pair" (core func $gp))
//   (type $tupT (tuple u32 u32))
//   (type $ft (func (result $tupT)))
//   (func $comp-get-pair (type $ft)
//     (canon lift (core func $gp) (memory $mem1) (realloc $r1)))
//
//   (core module $m2
//     (import "" "mem" (memory 1))
//     (import "" "get-pair" (func $im (param i32)))
//     (func (export "use-pair") (result i32)
//       ;; Hard-coded out-pointer at offset 1024 — well past the data segment
//       ;; at 16 and any realloc'd buffers from m1, which start at 256. Call
//       ;; the lowered core function with this ptr, then read back the first
//       u32 as
//       ;; the test signal.
//       i32.const 1024 call $im
//       i32.const 1024 i32.load))
//   (core func $core-get-pair-rt
//     (canon lower (func $comp-get-pair) (memory $mem1) (realloc $r1)))
