// === string payload OOB trap ===
// (component
//   ;; Lift result is tuple<string> → flat = [i32,i32] > MAX_FLAT_RESULTS=1, so
//   ;; canon lift takes the indirect path. The indirect-return area at @16
//   ;; encodes a string with ptr=64 and len=0x00100000 (1 MiB) — the module
//   ;; only provisions 1 page (64 KiB), so checkAccessBound must trap on the
//   ;; payload read. Exercises load_string's bounds-check on the (ptr,len)
//   ;; pair (separate from the existing string-len-cap trap).
//   (core module $m
//     (memory (export "mem") 1)
//     (data (i32.const 16) "\40\00\00\00\00\00\10\00")
//     (func (export "g") (result i32) i32.const 16)
//     (func (export "realloc") (param i32 i32 i32 i32) (result i32) i32.const
//     256))
//   (core instance $i (instantiate $m))
//   (alias core export $i "mem" (core memory $mem))
//   (alias core export $i "realloc" (core func $r))
//   (alias core export $i "g" (core func $g))
//   (type $tup (tuple string))
//   (type $ft (func (result $tup)))
//   (func (export "g") (type $ft)
//     (canon lift (core func $g) (memory $mem) (realloc $r))))
