// list<u32> indirect-result: exercises load_list and the loader's
// non-fixed-length list path.
TEST(ComponentCanonCoverage, IndirectReturnListU32) {
  Configure Conf;
  Conf.addProposal(Proposal::Component);
  VM::ComponentVM VM(Conf);
  ASSERT_TRUE(VM.loadWasm(list_u32_wasm));
  ASSERT_TRUE(VM.validate());
  ASSERT_TRUE(VM.instantiate());
  std::vector<ComponentValVariant> P;
  std::vector<ComponentValType> PT;
  auto Res = VM.execute("get", P, PT);
  ASSERT_TRUE(Res);
  ASSERT_EQ(Res->size(), 1u);
  auto &Vc = std::get<std::shared_ptr<ValComp>>((*Res)[0].first);
  ASSERT_TRUE(Vc);
  auto &L = std::get<ListVal>(Vc->V);
  ASSERT_EQ(L.Elements.size(), 3u);
  EXPECT_EQ(std::get<uint32_t>(L.Elements[0]), 1u);
  EXPECT_EQ(std::get<uint32_t>(L.Elements[1]), 2u);
  EXPECT_EQ(std::get<uint32_t>(L.Elements[2]), 3u);
}

// tuple<option<u32>, result<u32,string>>: load_option + load_result paths,
// each despecialised into a variant.
TEST(ComponentCanonCoverage, IndirectReturnOptionAndResult) {
  Configure Conf;
  Conf.addProposal(Proposal::Component);
  VM::ComponentVM VM(Conf);
  ASSERT_TRUE(VM.loadWasm(option_result_wasm));
  ASSERT_TRUE(VM.validate());
  ASSERT_TRUE(VM.instantiate());
  std::vector<ComponentValVariant> P;
  std::vector<ComponentValType> PT;
  auto Res = VM.execute("get", P, PT);
  ASSERT_TRUE(Res);
  ASSERT_EQ(Res->size(), 1u);
  auto &Vc = std::get<std::shared_ptr<ValComp>>((*Res)[0].first);
  ASSERT_TRUE(Vc);
  auto &Tup = std::get<TupleVal>(Vc->V);
  ASSERT_EQ(Tup.Values.size(), 2u);
  // option<u32> = Some(42).
  auto &Opt = std::get<std::shared_ptr<ValComp>>(Tup.Values[0]);
  ASSERT_TRUE(Opt);
  auto &OptV = std::get<OptionVal>(Opt->V);
  ASSERT_TRUE(OptV.Value.has_value());
  EXPECT_EQ(std::get<uint32_t>(*OptV.Value), 42u);
  // result<u32,string> = Err("hello").
  auto &Rv = std::get<std::shared_ptr<ValComp>>(Tup.Values[1]);
  ASSERT_TRUE(Rv);
  auto &Res2 = std::get<ResultVal>(Rv->V);
  EXPECT_FALSE(Res2.IsOk);
  ASSERT_TRUE(Res2.Payload.has_value());
  EXPECT_EQ(std::get<std::string>(*Res2.Payload), "hello");
}

// tuple<s8,u8,s16,u16,f32,f64,char,bool>: covers each primitive's load arm.
TEST(ComponentCanonCoverage, IndirectReturnPrimitiveMix) {
  Configure Conf;
  Conf.addProposal(Proposal::Component);
  VM::ComponentVM VM(Conf);
  ASSERT_TRUE(VM.loadWasm(primitives_wasm));
  ASSERT_TRUE(VM.validate());
  ASSERT_TRUE(VM.instantiate());
  std::vector<ComponentValVariant> P;
  std::vector<ComponentValType> PT;
  auto Res = VM.execute("g", P, PT);
  ASSERT_TRUE(Res);
  ASSERT_EQ(Res->size(), 1u);
  auto &Vc = std::get<std::shared_ptr<ValComp>>((*Res)[0].first);
  ASSERT_TRUE(Vc);
  auto &Tup = std::get<TupleVal>(Vc->V);
  ASSERT_EQ(Tup.Values.size(), 8u);
  EXPECT_EQ(std::get<int8_t>(Tup.Values[0]), int8_t{-1});
  EXPECT_EQ(std::get<uint8_t>(Tup.Values[1]), 0xABu);
  EXPECT_EQ(std::get<int16_t>(Tup.Values[2]), int16_t{-2});
  EXPECT_EQ(std::get<uint16_t>(Tup.Values[3]), 0xBEEFu);
  EXPECT_FLOAT_EQ(std::get<float>(Tup.Values[4]), 3.5f);
  EXPECT_DOUBLE_EQ(std::get<double>(Tup.Values[5]), 6.25);
  EXPECT_EQ(std::get<uint32_t>(Tup.Values[6]), 0x1F600u);
  EXPECT_TRUE(std::get<bool>(Tup.Values[7]));
}

// tuple<flags<3>, enum<3>>: load_flags + load_enum.
TEST(ComponentCanonCoverage, IndirectReturnFlagsAndEnum) {
  Configure Conf;
  Conf.addProposal(Proposal::Component);
  VM::ComponentVM VM(Conf);
  ASSERT_TRUE(VM.loadWasm(flags_enum_wasm));
  ASSERT_TRUE(VM.validate());
  ASSERT_TRUE(VM.instantiate());
  std::vector<ComponentValVariant> P;
  std::vector<ComponentValType> PT;
  auto Res = VM.execute("g", P, PT);
  ASSERT_TRUE(Res);
  ASSERT_EQ(Res->size(), 1u);
  auto &Vc = std::get<std::shared_ptr<ValComp>>((*Res)[0].first);
  ASSERT_TRUE(Vc);
  auto &Tup = std::get<TupleVal>(Vc->V);
  ASSERT_EQ(Tup.Values.size(), 2u);
  auto &Fp = std::get<std::shared_ptr<ValComp>>(Tup.Values[0]);
  ASSERT_TRUE(Fp);
  auto &Flags = std::get<FlagsVal>(Fp->V);
  ASSERT_EQ(Flags.Bits.size(), 3u);
  EXPECT_TRUE(Flags.Bits[0]);  // alpha
  EXPECT_FALSE(Flags.Bits[1]); // beta
  EXPECT_TRUE(Flags.Bits[2]);  // gamma
  auto &Ep = std::get<std::shared_ptr<ValComp>>(Tup.Values[1]);
  ASSERT_TRUE(Ep);
  EXPECT_EQ(std::get<EnumVal>(Ep->V).Case, 1u); // "second"
}

// Phase 2 / D — canon lower with a string param. Exercises the canon-lower
// path that stores the string into the caller's memory + length and threads
// (ptr, len) through to the lifted core importer.
TEST(ComponentCanonCoverage, LowerRoundtripStringLen) {
  Configure Conf;
  Conf.addProposal(Proposal::Component);
  VM::ComponentVM VM(Conf);
  ASSERT_TRUE(VM.loadWasm(lower_string_wasm));
  ASSERT_TRUE(VM.validate());
  ASSERT_TRUE(VM.instantiate());
  std::vector<ComponentValVariant> P{std::string{"abcdefgh"}};
  std::vector<ComponentValType> PT{ComponentValType(ComponentTypeCode::String)};
  auto Res = VM.execute("strlen-via-roundtrip", P, PT);
  ASSERT_TRUE(Res);
  ASSERT_EQ(Res->size(), 1u);
  EXPECT_EQ(std::get<uint32_t>((*Res)[0].first), 8u);
}

// A string of the embedder that is not UTF-8 is no value of the string type.
TEST(ComponentCanonCoverage, HostStringNotUtf8Rejected) {
  Configure Conf;
  Conf.addProposal(Proposal::Component);
  VM::ComponentVM VM(Conf);
  ASSERT_TRUE(VM.loadWasm(lower_string_wasm));
  ASSERT_TRUE(VM.validate());
  ASSERT_TRUE(VM.instantiate());
  std::vector<ComponentValType> PT{ComponentValType(ComponentTypeCode::String)};
  // A byte that starts nothing, a surrogate, a sequence cut short.
  for (const char *Bad : {"\xff\xfe", "\xed\xa0\x80", "a\xc3"}) {
    std::vector<ComponentValVariant> P{std::string{Bad}};
    auto Res = VM.execute("strlen-via-roundtrip", P, PT);
    ASSERT_FALSE(Res);
    EXPECT_EQ(Res.error(), ErrCode::Value::FuncSigMismatch);
  }

  // The message of an error context is a string as well.
  // (component
  //   (core module $M (func (export "take") (param i32)))
  //   (core instance $m (instantiate $M))
  //   (func (export "take") (param "e" error-context)
  //     (canon lift (core func $m "take"))))
  std::vector<uint8_t> Vec = {
      0x00, 0x61, 0x73, 0x6d, 0x0d, 0x00, 0x01, 0x00, 0x01, 0x23, 0x00, 0x61,
      0x73, 0x6d, 0x01, 0x00, 0x00, 0x00, 0x01, 0x05, 0x01, 0x60, 0x01, 0x7f,
      0x00, 0x03, 0x02, 0x01, 0x00, 0x07, 0x08, 0x01, 0x04, 0x74, 0x61, 0x6b,
      0x65, 0x00, 0x00, 0x0a, 0x04, 0x01, 0x02, 0x00, 0x0b, 0x02, 0x04, 0x01,
      0x00, 0x00, 0x00, 0x07, 0x08, 0x01, 0x40, 0x01, 0x01, 0x65, 0x64, 0x01,
      0x00, 0x06, 0x0a, 0x01, 0x00, 0x00, 0x01, 0x00, 0x04, 0x74, 0x61, 0x6b,
      0x65, 0x08, 0x06, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0b, 0x0a, 0x01,
      0x00, 0x04, 0x74, 0x61, 0x6b, 0x65, 0x01, 0x00, 0x00};
  VM::ComponentVM ErrVM(Conf);
  ASSERT_TRUE(ErrVM.loadWasm(Vec));
  ASSERT_TRUE(ErrVM.validate());
  ASSERT_TRUE(ErrVM.instantiate());
  std::vector<ComponentValVariant> Err{
      makeComponentVal(ErrorContextVal{"\xff"})};
  std::vector<ComponentValType> ErrType{
      ComponentValType(ComponentTypeCode::ErrContext)};
  auto Res = ErrVM.execute("take", Err, ErrType);
  ASSERT_FALSE(Res);
  EXPECT_EQ(Res.error(), ErrCode::Value::FuncSigMismatch);
}

