// =============================================================================
// FLT3 — result (list u8 4). Four elements flatten to 4 i32 (>
// MAX_FLAT_RESULTS), so the result is returned indirectly: the core function
// hands back a pointer and the lift loads the four bytes in place (load_list,
// fixed-length branch). Memory at offset 16 holds {1,2,3,4}.
//   (component
//     (core module $m
//       (memory (export "mem") 1)
//       (data (i32.const 16) "\01\02\03\04")
//       (func (export "get") (result i32) i32.const 16)
//       (func (export "realloc") (param i32 i32 i32 i32) (result i32)
//         i32.const 256))
