// =============================================================================
// A list of `u8` is one block of bytes: lifted as such, and lowered from it or
// from a list of `u8` values.
// (component
//   (core module $M
//     (memory (export "mem") 1)
//     (global $next (mut i32) (i32.const 1024))
//     (func (export "realloc") (param i32 i32 i32 i32) (result i32)
//       (global.get $next)
//       (global.set $next (i32.add (global.get $next) (local.get 3))))
//     ;; The list goes back as it came: its pointer and its length at 0.
//     (func (export "echo") (param i32 i32) (result i32)
//       (i32.store (i32.const 0) (local.get 0))
//       (i32.store (i32.const 4) (local.get 1))
//       (i32.const 0)))
//   (core instance $m (instantiate $M))
//   (func (export "echo") (param "x" (list u8)) (result (list u8))
//     (canon lift (core func $m "echo") (memory (core memory $m "mem"))
//       (realloc (core func $m "realloc")))))
TEST(ComponentCanonInvoke, ByteListRoundTrip) {
  Configure Conf;
  Conf.addProposal(Proposal::Component);
  VM::ComponentVM VM(Conf);

  std::vector<uint8_t> Vec = {
      0x00, 0x61, 0x73, 0x6d, 0x0d, 0x00, 0x01, 0x00, 0x01, 0x68, 0x00, 0x61,
      0x73, 0x6d, 0x01, 0x00, 0x00, 0x00, 0x01, 0x0f, 0x02, 0x60, 0x04, 0x7f,
      0x7f, 0x7f, 0x7f, 0x01, 0x7f, 0x60, 0x02, 0x7f, 0x7f, 0x01, 0x7f, 0x03,
      0x03, 0x02, 0x00, 0x01, 0x05, 0x03, 0x01, 0x00, 0x01, 0x06, 0x07, 0x01,
      0x7f, 0x01, 0x41, 0x80, 0x08, 0x0b, 0x07, 0x18, 0x03, 0x03, 0x6d, 0x65,
      0x6d, 0x02, 0x00, 0x07, 0x72, 0x65, 0x61, 0x6c, 0x6c, 0x6f, 0x63, 0x00,
      0x00, 0x04, 0x65, 0x63, 0x68, 0x6f, 0x00, 0x01, 0x0a, 0x20, 0x02, 0x0b,
      0x00, 0x23, 0x00, 0x23, 0x00, 0x20, 0x03, 0x6a, 0x24, 0x00, 0x0b, 0x12,
      0x00, 0x41, 0x00, 0x20, 0x00, 0x36, 0x02, 0x00, 0x41, 0x04, 0x20, 0x01,
      0x36, 0x02, 0x00, 0x41, 0x00, 0x0b, 0x02, 0x04, 0x01, 0x00, 0x00, 0x00,
      0x07, 0x0c, 0x03, 0x70, 0x7d, 0x70, 0x7d, 0x40, 0x01, 0x01, 0x78, 0x00,
      0x00, 0x01, 0x06, 0x1e, 0x03, 0x00, 0x00, 0x01, 0x00, 0x04, 0x65, 0x63,
      0x68, 0x6f, 0x00, 0x02, 0x01, 0x00, 0x03, 0x6d, 0x65, 0x6d, 0x00, 0x00,
      0x01, 0x00, 0x07, 0x72, 0x65, 0x61, 0x6c, 0x6c, 0x6f, 0x63, 0x08, 0x0a,
      0x01, 0x00, 0x00, 0x00, 0x02, 0x03, 0x00, 0x04, 0x01, 0x02, 0x0b, 0x0a,
      0x01, 0x00, 0x04, 0x65, 0x63, 0x68, 0x6f, 0x01, 0x00, 0x00};

  ASSERT_TRUE(VM.loadWasm(Vec));
  ASSERT_TRUE(VM.validate());
  ASSERT_TRUE(VM.instantiate());

  const std::vector<uint8_t> Bytes{1, 2, 3};
  std::vector<ComponentValVariant> Params{ComponentValVariant{Bytes}};
  std::vector<ComponentValType> NoPTypes;
  auto Res = VM.execute("echo", Params, NoPTypes);
  ASSERT_TRUE(Res);
  ASSERT_EQ(Res->size(), 1u);
  ASSERT_TRUE(std::holds_alternative<std::vector<uint8_t>>((*Res)[0].first));
  EXPECT_EQ(std::get<std::vector<uint8_t>>((*Res)[0].first), Bytes);

  ListVal List;
  for (const uint8_t Byte : Bytes) {
    List.Elements.emplace_back(Byte);
  }
  Params[0] = makeComponentVal(std::move(List));
  auto FromList = VM.execute("echo", Params, NoPTypes);
  ASSERT_TRUE(FromList);
  ASSERT_EQ(FromList->size(), 1u);
  ASSERT_TRUE(
      std::holds_alternative<std::vector<uint8_t>>((*FromList)[0].first));
  EXPECT_EQ(std::get<std::vector<uint8_t>>((*FromList)[0].first), Bytes);
}

// =============================================================================
// NaN canonicalization (CanonicalABI.md / definitions.py). WasmEdge
// follows the DETERMINISTIC_PROFILE, so every NaN crossing the canonical ABI
// collapses to the canonical quiet-NaN pattern. The five cases below exercise
// each primitive float conversion site:
//   lift_flat (T1 f64 / T5 f32) · load (T2) · lower_flat (T3) · store (T4).
// Binaries produced by `wasm-tools parse` from the .wat in each comment.

constexpr uint64_t kF64NonCanonicalNaN = 0x7ff4000000000000ull;
constexpr uint64_t kF64CanonicalNaN = 0x7ff8000000000000ull;
constexpr uint32_t kF32CanonicalNaN = 0x7fc00000u;

double f64FromBits(uint64_t B) noexcept {
  double D = 0.;
  std::memcpy(&D, &B, sizeof(D));
  return D;
}
uint64_t bitsOfF64(double D) noexcept {
  uint64_t B = 0;
  std::memcpy(&B, &D, sizeof(B));
  return B;
}
uint32_t bitsOfF32(float F) noexcept {
  uint32_t B = 0;
  std::memcpy(&B, &F, sizeof(B));
  return B;
}

// T1 — lift_flat f64 (site 3):
//   (component
//     (core module $m
//       (func (export "f") (result f64)
//         (f64.reinterpret_i64 (i64.const 0x7ff4000000000000))))
//     (core instance $i (instantiate $m))
//     (alias core export $i "f" (core func $f))
//     (type $ft (func (result f64)))
//     (func (export "nan-f64") (type $ft) (canon lift (core func $f))))
TEST(ComponentCanonInvoke, NanCanonicalizeLiftFlatF64) {
  Configure Conf;
  Conf.addProposal(Proposal::Component);
  VM::ComponentVM VM(Conf);

  std::vector<uint8_t> Vec = {
      0x00, 0x61, 0x73, 0x6d, 0x0d, 0x00, 0x01, 0x00, 0x01, 0x37, 0x00, 0x61,
      0x73, 0x6d, 0x01, 0x00, 0x00, 0x00, 0x01, 0x05, 0x01, 0x60, 0x00, 0x01,
      0x7c, 0x03, 0x02, 0x01, 0x00, 0x07, 0x05, 0x01, 0x01, 0x66, 0x00, 0x00,
      0x0a, 0x10, 0x01, 0x0e, 0x00, 0x42, 0x80, 0x80, 0x80, 0x80, 0x80, 0x80,
      0x80, 0xfa, 0xff, 0x00, 0xbf, 0x0b, 0x00, 0x09, 0x04, 0x6e, 0x61, 0x6d,
      0x65, 0x00, 0x02, 0x01, 0x6d, 0x02, 0x04, 0x01, 0x00, 0x00, 0x00, 0x06,
      0x07, 0x01, 0x00, 0x00, 0x01, 0x00, 0x01, 0x66, 0x07, 0x05, 0x01, 0x40,
      0x00, 0x00, 0x75, 0x08, 0x06, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x0b,
      0x0d, 0x01, 0x00, 0x07, 0x6e, 0x61, 0x6e, 0x2d, 0x66, 0x36, 0x34, 0x01,
      0x00, 0x00, 0x00, 0x2f, 0x0e, 0x63, 0x6f, 0x6d, 0x70, 0x6f, 0x6e, 0x65,
      0x6e, 0x74, 0x2d, 0x6e, 0x61, 0x6d, 0x65, 0x01, 0x06, 0x00, 0x00, 0x01,
      0x00, 0x01, 0x66, 0x01, 0x06, 0x00, 0x11, 0x01, 0x00, 0x01, 0x6d, 0x01,
      0x06, 0x00, 0x12, 0x01, 0x00, 0x01, 0x69, 0x01, 0x06, 0x03, 0x01, 0x00,
      0x02, 0x66, 0x74};

  ASSERT_TRUE(VM.loadWasm(Vec));
  ASSERT_TRUE(VM.validate());
  ASSERT_TRUE(VM.instantiate());

  std::vector<ComponentValVariant> NoParams;
  std::vector<ComponentValType> NoPTypes;
  auto Res = VM.execute("nan-f64", NoParams, NoPTypes);
  ASSERT_TRUE(Res);
  ASSERT_EQ(Res->size(), 1u);
  const double D = std::get<double>((*Res)[0].first);
  EXPECT_TRUE(std::isnan(D));
  EXPECT_EQ(bitsOfF64(D), kF64CanonicalNaN);
}

