// T3 — lower_flat f64 (site 4): host passes an f64 param, canonicalized before
// the core reinterprets it to i64. Also checks a normal double is unchanged.
TEST(ComponentCanonInvoke, NanCanonicalizeLowerFlatF64) {
  Configure Conf;
  Conf.addProposal(Proposal::Component);
  VM::ComponentVM VM(Conf);

  std::vector<uint8_t> Vec = {
      0x00, 0x61, 0x73, 0x6d, 0x0d, 0x00, 0x01, 0x00, 0x01, 0x32, 0x00, 0x61,
      0x73, 0x6d, 0x01, 0x00, 0x00, 0x00, 0x01, 0x06, 0x01, 0x60, 0x01, 0x7c,
      0x01, 0x7e, 0x03, 0x02, 0x01, 0x00, 0x07, 0x08, 0x01, 0x04, 0x62, 0x69,
      0x74, 0x73, 0x00, 0x00, 0x0a, 0x07, 0x01, 0x05, 0x00, 0x20, 0x00, 0xbd,
      0x0b, 0x00, 0x09, 0x04, 0x6e, 0x61, 0x6d, 0x65, 0x00, 0x02, 0x01, 0x6d,
      0x02, 0x04, 0x01, 0x00, 0x00, 0x00, 0x06, 0x0a, 0x01, 0x00, 0x00, 0x01,
      0x00, 0x04, 0x62, 0x69, 0x74, 0x73, 0x07, 0x08, 0x01, 0x40, 0x01, 0x01,
      0x78, 0x75, 0x00, 0x77, 0x08, 0x06, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00,
      0x0b, 0x0e, 0x01, 0x00, 0x08, 0x66, 0x36, 0x34, 0x2d, 0x62, 0x69, 0x74,
      0x73, 0x01, 0x00, 0x00, 0x00, 0x2f, 0x0e, 0x63, 0x6f, 0x6d, 0x70, 0x6f,
      0x6e, 0x65, 0x6e, 0x74, 0x2d, 0x6e, 0x61, 0x6d, 0x65, 0x01, 0x06, 0x00,
      0x00, 0x01, 0x00, 0x01, 0x62, 0x01, 0x06, 0x00, 0x11, 0x01, 0x00, 0x01,
      0x6d, 0x01, 0x06, 0x00, 0x12, 0x01, 0x00, 0x01, 0x69, 0x01, 0x06, 0x03,
      0x01, 0x00, 0x02, 0x66, 0x74};

  ASSERT_TRUE(VM.loadWasm(Vec));
  ASSERT_TRUE(VM.validate());
  ASSERT_TRUE(VM.instantiate());

  std::vector<ComponentValType> PTypes{
      ComponentValType(ComponentTypeCode::F64)};

  std::vector<ComponentValVariant> NanParam{
      ComponentValVariant{f64FromBits(kF64NonCanonicalNaN)}};
  auto Res = VM.execute("f64-bits", NanParam, PTypes);
  ASSERT_TRUE(Res);
  ASSERT_EQ(Res->size(), 1u);
  EXPECT_EQ(std::get<uint64_t>((*Res)[0].first), kF64CanonicalNaN);

  // Regression: a normal (non-NaN) double passes through bit-for-bit.
  std::vector<ComponentValVariant> NormalParam{ComponentValVariant{2.5}};
  auto Res2 = VM.execute("f64-bits", NormalParam, PTypes);
  ASSERT_TRUE(Res2);
  ASSERT_EQ(Res2->size(), 1u);
  EXPECT_EQ(std::get<uint64_t>((*Res2)[0].first), bitsOfF64(2.5));
}

