// =============================================================================
// Non-UTF-8 string encodings (CanonicalABI.md `string-encoding` option). The
// host string is always UTF-8; lower encodes it to the guest layout and lift
// decodes it back. Each component exports `roundtrip` (string->string, echoes
// the lowered (ptr,tagged) so lift re-decodes exactly what lower wrote) and
// `cu` (string->u32, returns the guest tagged_code_units). Binaries produced by
// `wasm-tools parse` from this source, with the encoding of each test:
//   (component
//     (core module $m
//       (memory (export "mem") 1)
//       (global $next (mut i32) (i32.const 8))
//       ;; An aligning bump allocator: a shrink keeps the block, a growth
//       ;; copies it.
//       (func (export "realloc") (param $old i32) (param $osz i32)
//                                (param $align i32) (param $nsz i32)
//                                (result i32)
//         (local $r i32)
//         (if (local.get $old)
//           (then (if (i32.le_u (local.get $nsz) (local.get $osz))
//             (then (return (local.get $old))))))
//         (local.set $r (i32.and
//           (i32.add (global.get $next)
//                    (i32.sub (local.get $align) (i32.const 1)))
//           (i32.xor (i32.sub (local.get $align) (i32.const 1))
//                    (i32.const -1))))
//         (global.set $next (i32.add (local.get $r) (local.get $nsz)))
//         (memory.copy (local.get $r) (local.get $old) (local.get $osz))
//         (local.get $r))
//       ;; Echo the lowered (ptr, tagged) pair as the indirect result at 0.
//       (func (export "id") (param $ptr i32) (param $tag i32) (result i32)
//         (i32.store (i32.const 0) (local.get $ptr))
//         (i32.store (i32.const 4) (local.get $tag))
//         (i32.const 0))
//       (func (export "cu") (param $ptr i32) (param $tag i32) (result i32)
//         (local.get $tag)))
//     (core instance $i (instantiate $m))
//     (alias core export $i "mem" (core memory $mem))
//     (alias core export $i "realloc" (core func $r))
//     (alias core export $i "id" (core func $fid))
//     (alias core export $i "cu" (core func $fcu))
//     (func (export "roundtrip") (param "s" string) (result string)
//       (canon lift (core func $fid) (memory $mem) (realloc $r)
//         string-encoding=utf16))
//     (func (export "cu") (param "s" string) (result u32)
//       (canon lift (core func $fcu) (memory $mem) (realloc $r)
//         string-encoding=utf16)))

// UTF-8 byte sequences for the test strings, built from explicit bytes so the
// compiler's narrow execution charset can't reinterpret them.
//   Aeyo = U+0041 U+00E9 U+10437 (1 + 2 + 4 UTF-8 bytes)
//   Cafe = U+0063 U+0061 U+0066 U+00E9
//   Ayo  = U+0041 U+10437
static const std::string Utf8_Aeyo({'\x41', '\xC3', '\xA9', '\xF0', '\x90',
                                    '\x90', '\xB7'});
static const std::string Utf8_Cafe({'\x63', '\x61', '\x66', '\xC3', '\xA9'});
static const std::string Utf8_Ayo({'\x41', '\xF0', '\x90', '\x90', '\xB7'});

