// A string transcoded between two guests is allocated by the encoding it
// comes from. Lower number 3 * source + destination of $D sends a string of
// its memory to $C, whose realloc logs its calls:
// (component
//   (component $C
//     (core module $M
//       (memory (export "mem") 1)
//       (global $n (mut i32) (i32.const 0))
//       (global $len (mut i32) (i32.const 0))
//       ;; Log (old size, align, new size) of every call from 1024 on, and
//       ;; always hand out the block at 16.
//       (func (export "realloc") (param $old i32) (param $osz i32)
//                                (param $align i32) (param $nsz i32)
//                                (result i32)
//         (local $at i32)
//         (local.set $at (i32.add (i32.const 1024)
//                                 (i32.mul (global.get $n) (i32.const 12))))
//         (i32.store (local.get $at) (local.get $osz))
//         (i32.store offset=4 (local.get $at) (local.get $align))
//         (i32.store offset=8 (local.get $at) (local.get $nsz))
//         (global.set $n (i32.add (global.get $n) (i32.const 1)))
//         (i32.const 16))
//       (func (export "take") (param $ptr i32) (param $len i32)
//         (global.set $len (local.get $len)))
//       (func (export "reset") (global.set $n (i32.const 0)))
//       (func (export "calls") (result i32) (global.get $n))
//       ;; Word $i of the log.
//       (func (export "call") (param $i i32) (result i32)
//         (i32.load (i32.add (i32.const 1024)
//                            (i32.mul (local.get $i) (i32.const 4)))))
//       ;; The tagged code units and the bytes of the string taken last.
//       (func (export "len") (result i32) (global.get $len))
//       (func (export "byte") (param $i i32) (result i32)
//         (i32.load8_u (i32.add (i32.const 16) (local.get $i)))))
//     (core instance $m (instantiate $M))
//     (func (export "take-utf8") (param "s" string)
//       (canon lift (core func $m "take") string-encoding=utf8
//         (memory (core memory $m "mem")) (realloc (core func $m "realloc"))))
//     (func (export "take-utf16") (param "s" string)
//       (canon lift (core func $m "take") string-encoding=utf16
//         (memory (core memory $m "mem")) (realloc (core func $m "realloc"))))
//     (func (export "take-latin1") (param "s" string)
//       (canon lift (core func $m "take") string-encoding=latin1+utf16
//         (memory (core memory $m "mem")) (realloc (core func $m "realloc"))))
//     (func (export "reset") (canon lift (core func $m "reset")))
//     (func (export "calls") (result u32) (canon lift (core func $m "calls")))
//     (func (export "call") (param "i" u32) (result u32)
//       (canon lift (core func $m "call")))
//     (func (export "len") (result u32) (canon lift (core func $m "len")))
//     (func (export "byte") (param "i" u32) (result u32)
//       (canon lift (core func $m "byte"))))
//   (component $D
//     (import "take-utf8" (func $t0 (param "s" string)))
//     (import "take-utf16" (func $t1 (param "s" string)))
//     (import "take-latin1" (func $t2 (param "s" string)))
//     (core module $Mem
//       (memory (export "mem") 1)
//       ;; "ab": UTF-8 and Latin-1 at 0, UTF-16 at 8.
//       (data (i32.const 0) "ab")
//       (data (i32.const 8) "a\00b\00")
//       ;; "h\u{e9}": UTF-8 at 16, UTF-16 at 24, Latin-1 at 32.
//       (data (i32.const 16) "h\c3\a9")
//       (data (i32.const 24) "h\00\e9\00")
//       (data (i32.const 32) "h\e9")
//       ;; "h\u{6c34}": UTF-8 at 40, UTF-16 at 48.
//       (data (i32.const 40) "h\e6\b0\b4")
//       (data (i32.const 48) "h\00\34\6c")
//       ;; "a\u{1f370}": UTF-8 at 56, UTF-16 at 64.
//       (data (i32.const 56) "a\f0\9f\8d\b0")
//       (data (i32.const 64) "a\00\3c\d8\70\df"))
//     (core instance $mem (instantiate $Mem))
//     ;; Lower number 3 * source + destination, in the order utf8, utf16,
//     ;; latin1+utf16.
//     (canon lower (func $t0) string-encoding=utf8
//       (memory (core memory $mem "mem")) (core func $f0))
//     (canon lower (func $t1) string-encoding=utf8
//       (memory (core memory $mem "mem")) (core func $f1))
//     (canon lower (func $t2) string-encoding=utf8
//       (memory (core memory $mem "mem")) (core func $f2))
//     (canon lower (func $t0) string-encoding=utf16
//       (memory (core memory $mem "mem")) (core func $f3))
//     (canon lower (func $t1) string-encoding=utf16
//       (memory (core memory $mem "mem")) (core func $f4))
//     (canon lower (func $t2) string-encoding=utf16
//       (memory (core memory $mem "mem")) (core func $f5))
//     (canon lower (func $t0) string-encoding=latin1+utf16
//       (memory (core memory $mem "mem")) (core func $f6))
//     (canon lower (func $t1) string-encoding=latin1+utf16
//       (memory (core memory $mem "mem")) (core func $f7))
//     (canon lower (func $t2) string-encoding=latin1+utf16
//       (memory (core memory $mem "mem")) (core func $f8))
//     (core module $M
//       (type $take (func (param i32 i32)))
//       (import "" "0" (func $f0 (type $take)))
//       (import "" "1" (func $f1 (type $take)))
//       (import "" "2" (func $f2 (type $take)))
//       (import "" "3" (func $f3 (type $take)))
//       (import "" "4" (func $f4 (type $take)))
//       (import "" "5" (func $f5 (type $take)))
//       (import "" "6" (func $f6 (type $take)))
//       (import "" "7" (func $f7 (type $take)))
//       (import "" "8" (func $f8 (type $take)))
//       (table 9 9 funcref)
//       (elem (i32.const 0) func $f0 $f1 $f2 $f3 $f4 $f5 $f6 $f7 $f8)
//       (func (export "send")
//             (param $sel i32) (param $ptr i32) (param $len i32)
//         (call_indirect (type $take)
//           (local.get $ptr) (local.get $len) (local.get $sel))))
//     (core instance $m (instantiate $M (with "" (instance
//       (export "0" (func $f0)) (export "1" (func $f1)) (export "2" (func $f2))
//       (export "3" (func $f3)) (export "4" (func $f4)) (export "5" (func $f5))
//       (export "6" (func $f6)) (export "7" (func $f7))
//       (export "8" (func $f8))))))
//     (func (export "send")
//           (param "sel" u32) (param "ptr" u32) (param "len" u32)
//       (canon lift (core func $m "send"))))
//   (instance $c (instantiate $C))
//   (instance $d (instantiate $D
//     (with "take-utf8" (func $c "take-utf8"))
//     (with "take-utf16" (func $c "take-utf16"))
//     (with "take-latin1" (func $c "take-latin1"))))
//   (func (export "send") (alias export $d "send"))
//   (func (export "reset") (alias export $c "reset"))
//   (func (export "calls") (alias export $c "calls"))
//   (func (export "call") (alias export $c "call"))
//   (func (export "len") (alias export $c "len"))
//   (func (export "byte") (alias export $c "byte")))
