// =============================================================================
// Runtime resource support: canon resource.new / resource.rep / resource.drop
// over the canonical handle table, own/borrow transfer through lift/lower,
// and destructor invocation on dropping an owned handle.
//
// (component
//   (core module $m
//     (global $dtors (mut i32) (i32.const 0))
//     (func (export "dtor") (param i32)
//       global.get $dtors i32.const 1 i32.add global.set $dtors)
//     (func (export "dtor-count") (result i32) global.get $dtors))
//   (core instance $i (instantiate $m))
//   (alias core export $i "dtor" (core func $dtor))
//   (type $r (resource (rep i32) (dtor (func $dtor))))
//   (export $r2 "r" (type $r))
//   (core func $new (canon resource.new $r))
//   (core func $rep (canon resource.rep $r))
//   (core func $drop (canon resource.drop $r))
//   (core module $logic
//     (import "" "new" (func $new (param i32) (result i32)))
//     (import "" "rep" (func $rep (param i32) (result i32)))
//     (import "" "drop" (func $drop (param i32)))
//     (func (export "make") (param i32) (result i32) ;; new + rep coverage
//     (func (export "peek") (param i32) (result i32) local.get 0) ;; owner
//     borrow = rep (func (export "free") (param i32) local.get 0 call $drop))
//   (core instance $li (instantiate $logic (with "" (instance
//     (export "new" (func $new)) (export "rep" (func $rep))
//     (export "drop" (func $drop))))))
//   (type $own (own $r2))
//   (func (export "make") (func (param "rep" u32) (result $own))
//     (canon lift (core func $li "make")))
//   (type $borrow (borrow $r2))
//   (func (export "peek") (func (param "h" $borrow) (result u32))
//     (canon lift (core func $li "peek")))
//   (func (export "free") (func (param "h" $own))
//     (canon lift (core func $li "free")))
//   (alias core export $i "dtor-count" (core func $dc))
//   (func (export "dtor-count") (func (result u32))
//     (canon lift (core func $dc))))
