TEST(ComponentCanonInvoke, ResourceNewRepDropRoundtrip) {
  Configure Conf;
  Conf.addProposal(Proposal::Component);
  VM::ComponentVM VM(Conf);
  ASSERT_TRUE(VM.loadWasm(Wat_ResourceRoundtrip));
  ASSERT_TRUE(VM.validate());
  ASSERT_TRUE(VM.instantiate());

  // make(41) creates a handle in the table of the component and transfers
  // ownership out. The host-side own value carries the representation.
  std::vector<ComponentValVariant> MakeArgs{ComponentValVariant{uint32_t(41)}};
  std::vector<ComponentValType> MakeTypes{
      ComponentValType(ComponentTypeCode::U32)};
  auto MakeRes = VM.execute("make", MakeArgs, MakeTypes);
  ASSERT_TRUE(MakeRes);
  ASSERT_EQ(MakeRes->size(), 1u);
  auto &OwnVc = std::get<std::shared_ptr<ValComp>>((*MakeRes)[0].first);
  ASSERT_TRUE(OwnVc);
  const uint64_t OwnRep = std::get<OwnVal>(OwnVc->V).Handle;
  EXPECT_EQ(OwnRep, 41u);

  // peek(borrow) lowers a borrow into the table. resource.rep then reads the
  // representation back.
  std::vector<ComponentValVariant> PeekArgs{
      makeComponentVal(BorrowVal{OwnRep})};
  std::vector<ComponentValType> PeekTypes{ComponentValType(4)};
  auto PeekRes = VM.execute("peek", PeekArgs, PeekTypes);
  ASSERT_TRUE(PeekRes);
  EXPECT_EQ(std::get<uint32_t>((*PeekRes)[0].first), 41u);

  // No destructor has run yet.
  std::vector<ComponentValVariant> NoArgs;
  std::vector<ComponentValType> NoTypes;
  auto Count0 = VM.execute("dtor-count", NoArgs, NoTypes);
  ASSERT_TRUE(Count0);
  EXPECT_EQ(std::get<uint32_t>((*Count0)[0].first), 0u);

  // free(own) lowers ownership back into the table. resource.drop then runs
  // the destructor exactly once.
  std::vector<ComponentValVariant> FreeArgs{makeComponentVal(OwnVal{OwnRep})};
  std::vector<ComponentValType> FreeTypes{ComponentValType(2)};
  ASSERT_TRUE(VM.execute("free", FreeArgs, FreeTypes));
  auto Count1 = VM.execute("dtor-count", NoArgs, NoTypes);
  ASSERT_TRUE(Count1);
  EXPECT_EQ(std::get<uint32_t>((*Count1)[0].first), 1u);
}

