// (component
//   (type $r (resource (rep i64)))
//   (export $r2 "r" (type $r))
//   (type $o (own $r2))
//   (type $b (borrow $r2))
//   (core module $m
//     (import "" "new" (func $new (param i64) (result i32)))
//     (import "" "drop" (func $drop (param i32)))
//     (func (export "make") (param i64) (result i32) (call $new (local.get 0)))
//     (func (export "peek") (param i64) (result i64) (local.get 0))
//     (func (export "free") (param i32) (call $drop (local.get 0))))
//   (core func $new (canon resource.new $r))
//   (core func $drop (canon resource.drop $r))
//   (core instance $i (instantiate $m (with "" (instance
//     (export "new" (func $new)) (export "drop" (func $drop))))))
