TEST(ComponentCanonInvoke, BorrowRepI64IntoImplementer) {
  Configure Conf;
  Conf.addProposal(Proposal::Component);
  Conf.addProposal(Proposal::Memory64);
  // A representation above 2^32 shows any truncation to a 32-bit handle.
  const uint64_t Rep = UINT64_C(0x0000002a00000029);
  std::vector<ComponentValVariant> MakeArgs{ComponentValVariant{Rep}};
  std::vector<ComponentValType> MakeTypes{
      ComponentValType(ComponentTypeCode::U64)};
  // Type indices: 0 = $r, 1 = $r2, 2 = $o, 3 = $b.
  const ComponentValType OwnType(2), BorrowType(3);

  {
    VM::ComponentVM VM(Conf);
    ASSERT_TRUE(VM.loadWasm(Wat_BorrowRepI64Flat));
    ASSERT_TRUE(VM.validate());
    ASSERT_TRUE(VM.instantiate());
    auto MakeRes = VM.execute("make", MakeArgs, MakeTypes);
    ASSERT_TRUE(MakeRes);
    auto &OwnVc = std::get<std::shared_ptr<ValComp>>((*MakeRes)[0].first);
    ASSERT_TRUE(OwnVc);
    EXPECT_EQ(std::get<OwnVal>(OwnVc->V).Handle, Rep);
    // The flat parameter carries the whole representation.
    std::vector<ComponentValVariant> PeekArgs{makeComponentVal(BorrowVal{Rep})};
    std::vector<ComponentValType> PeekTypes{BorrowType};
    auto PeekRes = VM.execute("peek", PeekArgs, PeekTypes);
    ASSERT_TRUE(PeekRes);
    EXPECT_EQ(std::get<uint64_t>((*PeekRes)[0].first), Rep);
    std::vector<ComponentValVariant> FreeArgs{makeComponentVal(OwnVal{Rep})};
    std::vector<ComponentValType> FreeTypes{OwnType};
    EXPECT_TRUE(VM.execute("free", FreeArgs, FreeTypes));
  }
  {
    VM::ComponentVM VM(Conf);
    ASSERT_TRUE(VM.loadWasm(Wat_BorrowRepI64Memory));
    ASSERT_TRUE(VM.validate());
    ASSERT_TRUE(VM.instantiate());
    ASSERT_TRUE(VM.execute("make", MakeArgs, MakeTypes));
    // The tuple in memory stores the representation as an 8-byte field.
    std::vector<ComponentValVariant> PeekArgs(16,
                                              ComponentValVariant{uint32_t(7)});
    PeekArgs.push_back(makeComponentVal(BorrowVal{Rep}));
    std::vector<ComponentValType> PeekTypes(
        16, ComponentValType(ComponentTypeCode::U32));
    PeekTypes.push_back(BorrowType);
    auto PeekRes = VM.execute("peek", PeekArgs, PeekTypes);
    ASSERT_TRUE(PeekRes);
    EXPECT_EQ(std::get<uint64_t>((*PeekRes)[0].first), Rep);
  }
}

