TEST(ComponentInvoke, InterfaceExportedFunction) {
  Configure Conf;
  Conf.addProposal(Proposal::Component);
  VM::ComponentVM VM(Conf);
  ASSERT_TRUE(VM.loadWasm(Wat_IfaceExport));
  ASSERT_TRUE(VM.validate());
  ASSERT_TRUE(VM.instantiate());

  // The function is listed under its qualified path, not at the top level.
  const auto Funcs = VM.getFunctionList();
  ASSERT_EQ(Funcs.size(), 1u);
  EXPECT_EQ(Funcs[0].first, "docs:adder/add@0.1.0#add");

  std::vector<ComponentValVariant> Args{uint32_t(20), uint32_t(22)};
  std::vector<ComponentValType> Types{ComponentValType(ComponentTypeCode::U32),
                                      ComponentValType(ComponentTypeCode::U32)};
  auto Res = VM.execute("docs:adder/add@0.1.0#add", Args, Types);
  ASSERT_TRUE(Res);
  ASSERT_EQ(Res->size(), 1u);
  EXPECT_EQ(std::get<uint32_t>((*Res)[0].first), 42u);

  // An unqualified or unknown path still misses.
  EXPECT_FALSE(VM.execute("add", Args, Types));
  EXPECT_FALSE(VM.execute("docs:adder/add@0.1.0#sub", Args, Types));
}

