// The parameters of `run` are an enum, a variant and a flags value; it sums
// the case of each, the payload and the bits as decimal digits.
// (component
//   (type $e' (enum "a" "b"))
//   (export $e "e" (type $e'))
//   (type $v' (variant (case "x") (case "y" u32)))
//   (export $v "v" (type $v'))
//   (type $p' (flags "r" "w"))
//   (export $p "p" (type $p'))
//   (core module $M
//     ;; The enum case, the variant case, its payload and the flag bits.
//     (func (export "run") (param i32 i32 i32 i32) (result i32)
//       (i32.add
//         (i32.add (local.get 0) (i32.mul (local.get 1) (i32.const 10)))
//         (i32.add (i32.mul (local.get 2) (i32.const 100))
//           (i32.mul (local.get 3) (i32.const 1000))))))
//   (core instance $m (instantiate $M))
//   (func (export "run") (param "c" $e) (param "v" $v) (param "p" $p)
//     (result u32) (canon lift (core func $m "run"))))
